#!/usr/bin/env python3
import json, base64, urllib.request, urllib.parse, time, sys, hashlib

TOKEN   = "skbUvbYYIvf0Uwc43kqoHa7MX556BIABP7tNDQjW06yeBHY9ImiPeEjgMs87ZxlUafA5XRt6LXwn8d5Y9JcmDaZN13fvjxt6Tm3QgSAE8LqSvP6oU7zgF3W4dGb3jnjVIuBnZTICBsln2LHqgKjFIAybBohK6JCJWR8qHmP6CMhPVpsiPB79"
PROJECT = "vbnsqnkg"
BASE    = "https://" + PROJECT + ".api.sanity.io/v2024-01-01/data"

print("Script starting...", flush=True)

# Test connection to Sanity first
try:
    test_url = BASE + "/query/production?query=" + urllib.parse.quote('*[_type == "outreachTemplate"][0]._id')
    test_req = urllib.request.Request(test_url, headers={"Authorization": "Bearer " + TOKEN})
    with urllib.request.urlopen(test_req) as r:
        result = json.loads(r.read())
        print("Sanity connection OK, got: " + str(result)[:100], flush=True)
except Exception as e:
    print("Sanity connection FAILED: " + str(e), flush=True)
    sys.exit(1)

TEMPLATES_B64 = ""
TEMPLATES = json.loads(base64.b64decode(TEMPLATES_B64).decode("utf-8"))
print("Loaded " + str(len(TEMPLATES)) + " templates", flush=True)

created = updated = errors = 0

for tmpl in TEMPLATES:
    name = tmpl["name"]
    try:
        groq = '*[_type == "outreachTemplate" && name == $n][0]._id'
        existing = sanity_query(groq, {"n": name})
        doc = {
            "_type": "outreachTemplate",
            "name": name,
            "type": tmpl["type"],
            "subject": tmpl["subject"],
            "previewText": tmpl.get("previewText", ""),
            "body": tmpl["body"],
            "variables": tmpl.get("variables", []),
            "isActive": True,
        }
        if existing:
            sanity_mutate([{"patch": {"id": existing, "set": doc}}])
            updated += 1
            print("  UPDATED: " + name[:60], flush=True)
        else:
            doc_id = "template-" + hashlib.md5(name.encode()).hexdigest()[:16]
            doc["_id"] = doc_id
            sanity_mutate([{"createOrReplace": doc}])
            created += 1
            print("  CREATED: " + name[:60], flush=True)
        time.sleep(0.3)
    except Exception as e:
        errors += 1
        print("  ERROR " + name[:40] + ": " + str(e), flush=True)

print("", flush=True)
print("DONE: " + str(created) + " created, " + str(updated) + " updated, " + str(errors) + " errors", flush=True)
if errors > 0:
    sys.exit(1)
